# DEBUG AREA 1N2 (HIGH-TUNDRA)
@token    = debug-area-1n2
@name     = DEBUG Area 1N2
@level    = 50
@size     = 50 x 16
@sheet    = mmrpg-overworld-2k25
#---------------------------#
@portals[]  = spawn(25-13, hidden)
#---------------------------#
@portals[]  = subspace-portal(23-5, debug-area-0__arctic-portal, purple-alt)
@locks[]    = crystal-portal-flower(23-5, portal-flower, crystal, items:crystal-core, x10, locked)
